  /**
   * @method
   * @name alpaca#createOrder
   * @description create a trade order
   * @see https://docs.::getValue(alpaca,
   * std::string("markets"))/reference/postorder
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market', 'limit' or 'stop_limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {float} [params.triggerPrice] The price at which a trigger order is
   * triggered at
   * @param {float} [params.cost] *market orders only* the cost of the order in
   * units of the quote currency
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createOrder(ccxt::any symbol, ccxt::any type, ccxt::any side,
              ccxt::any amount, ccxt::any price = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> ccxt::any {
                if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                ccxt::any market = this->market(symbol);
                ccxt::any id = ::getValue(market, std::string("id"));
                ccxt::any request = ccxt::dict{
                    {std::string("symbol"), id},
                    {std::string("side"), side},
                    {std::string("type"), type},
                };
                ccxt::any triggerPrice =
                    this->safeString2(params, std::string("triggerPrice"),
                                      std::string("stop_price"));
                if (isTrue(!isEqual(triggerPrice, ccxt::any{}))) {
                  ccxt::any newType = ccxt::any{};
                  if (isTrue(isGreaterThanOrEqual(
                          getIndexOf(type, std::string("limit")), 0))) {
                    newType = std::string("stop_limit");
                  } else {
                    throw NotSupported(toString(add(
                        add(add(this->id,
                                std::string(" createOrder() does not support "
                                            "stop orders for ")),
                            type),
                        std::string(
                            " orders, only stop_limit orders are supported"))));
                  }
                  ::setValue(request, std::string("stop_price"),
                             this->priceToPrecision(symbol, triggerPrice));
                  ::setValue(request, std::string("type"), newType);
                }
                if (isTrue(isGreaterThanOrEqual(
                        getIndexOf(type, std::string("limit")), 0))) {
                  ::setValue(request, std::string("limit_price"),
                             this->priceToPrecision(symbol, price));
                }
                ccxt::any cost = this->safeString(params, std::string("cost"));
                if (isTrue(!isEqual(cost, ccxt::any{}))) {
                  params = this->omit(params, std::string("cost"));
                  ::setValue(request, std::string("notional"),
                             this->costToPrecision(symbol, cost));
                } else {
                  ::setValue(request, std::string("qty"),
                             this->amountToPrecision(symbol, amount));
                }
                ccxt::any defaultTIF = ccxt::any{};
                ccxt::any defaultTIFparamsVariable =
                    this->handleOptionAndParams(params,
                                                std::string("createOrder"),
                                                std::string("timeInForce"));
                defaultTIF = ::getValue(defaultTIFparamsVariable, 0);
                params = ::getValue(defaultTIFparamsVariable, 1);
                ::setValue(request, std::string("time_in_force"), defaultTIF);
                params =
                    this->omit(params, ccxt::list{std::string("timeInForce"),
                                                  std::string("triggerPrice")});
                ::setValue(request, std::string("client_order_id"),
                           this->generateClientOrderId(params));
                params = this->omit(params,
                                    ccxt::list{std::string("clientOrderId")});
                ccxt::any order = awaitValue(this->traderPrivatePostV2Orders(
                    this->extend(request, params)));
                //
                //   {
                //      "id": "61e69015-8549-4bfd-b9c3-01e75843f47d",
                //      "client_order_id":
                //      "eb9e2aaa-f71a-4f51-b5b4-52a6c565dad4", "created_at":
                //      "2021-03-16T18:38:01.942282Z", "updated_at":
                //      "2021-03-16T18:38:01.942282Z", "submitted_at":
                //      "2021-03-16T18:38:01.937734Z", "filled_at": null,
                //      "expired_at": null,
                //      "canceled_at": null,
                //      "failed_at": null,
                //      "replaced_at": null,
                //      "replaced_by": null,
                //      "replaces": null,
                //      "asset_id": "b0b6dd9d-8b9b-48a9-ba46-b9d54906e415",
                //      "symbol": "AAPL",
                //      "asset_class": "us_equity",
                //      "notional": "500",
                //      "qty": null,
                //      "filled_qty": "0",
                //      "filled_avg_price": null,
                //      "order_class": "",
                //      "order_type": "market",
                //      "type": "market",
                //      "side": "buy",
                //      "time_in_force": "day",
                //      "limit_price": null,
                //      "stop_price": null,
                //      "status": "accepted",
                //      "extended_hours": false,
                //      "legs": null,
                //      "trail_percent": null,
                //      "trail_price": null,
                //      "hwm": null
                //   }
                //
                return this->parseOrder(order, market);
              })
            .share();
  }

  /**
   * @method
   * @name alpaca#cancelOrder
   * @description cancels an open order
   * @see https://docs.::getValue(alpaca,
   * std::string("markets"))/reference/deleteorderbyorderid
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any request = ccxt::dict{
                            {std::string("order_id"), id},
                        };
                        ccxt::any response =
                            awaitValue(this->traderPrivateDeleteV2OrdersOrderId(
                                this->extend(request, params)));
                        //
                        //   {
                        //       "code": 40410000,
                        //       "message": "order is not found."
                        //   }
                        //
                        return this->parseOrder(response);
                      })
        .share();
  }

  /**
   * @method
   * @name alpaca#cancelAllOrders
   * @description cancel all open orders in a market
   * @see https://docs.::getValue(alpaca,
   * std::string("markets"))/reference/deleteallorders
   * @param {string} [symbol] alpaca cancelAllOrders cannot setting symbol, it
   * will cancel all open orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelAllOrders(ccxt::any symbol = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any response = awaitValue(
                            this->traderPrivateDeleteV2Orders(params));
                        if (isTrue(isArray(response))) {
                          return this->parseOrders(response);
                        } else {
                          return ccxt::list{this->safeOrder(ccxt::dict{
                              {std::string("info"), response},
                          })};
                        }
                        return ccxt::any{};
                      })
        .share();
  }

  /**
   * @method
   * @name alpaca#fetchOrder
   * @description fetches information on an order made by the user
   * @see https://docs.::getValue(alpaca,
   * std::string("markets"))/reference/getorderbyorderid
   * @param {string} id the order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any request = ccxt::dict{
                            {std::string("order_id"), id},
                        };
                        ccxt::any order =
                            awaitValue(this->traderPrivateGetV2OrdersOrderId(
                                this->extend(request, params)));
                        ccxt::any marketId =
                            this->safeString(order, std::string("symbol"));
                        ccxt::any market = this->safeMarket(marketId);
                        return this->parseOrder(order, market);
                      })
        .share();
  }

  /**
   * @method
   * @name alpaca#fetchOrders
   * @description fetches information on multiple orders made by the user
   * @see https://docs.::getValue(alpaca,
   * std::string("markets"))/reference/getallorders
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch orders for
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("status"), std::string("all")},
                 };
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbols"),
                              ::getValue(market, std::string("id")));
                 }
                 ccxt::any until =
                     this->safeInteger(params, std::string("until"));
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   params = this->omit(params, std::string("until"));
                   ::setValue(request, std::string("endTime"),
                              this->iso8601(until));
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("after"),
                              this->iso8601(since));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any response = awaitValue(this->traderPrivateGetV2Orders(
                     this->extend(request, params)));
                 //
                 //     [
                 //         {
                 //           "id": "cbaf12d7-69b8-49c0-a31b-b46af35c755c",
                 //           "client_order_id":
                 //           "ccxt_b36156ae6fd44d098ac9c179bab33efd",
                 //           "created_at": "2023-11-17T04:21:42.234579Z",
                 //           "updated_at": "2023-11-17T04:22:34.442765Z",
                 //           "submitted_at": "2023-11-17T04:21:42.233357Z",
                 //           "filled_at": null,
                 //           "expired_at": null,
                 //           "canceled_at": "2023-11-17T04:22:34.399019Z",
                 //           "failed_at": null,
                 //           "replaced_at": null,
                 //           "replaced_by": null,
                 //           "replaces": null,
                 //           "asset_id":
                 //           "77c6f47f-0939-4b23-b41e-47b4469c4bc8", "symbol":
                 //           "LTC/USDT", "asset_class": "crypto", "notional":
                 //           null, "qty": "0.001", "filled_qty": "0",
                 //           "filled_avg_price": null,
                 //           "order_class": "",
                 //           "order_type": "limit",
                 //           "type": "limit",
                 //           "side": "sell",
                 //           "time_in_force": "gtc",
                 //           "limit_price": "1000",
                 //           "stop_price": null,
                 //           "status": "canceled",
                 //           "extended_hours": false,
                 //           "legs": null,
                 //           "trail_percent": null,
                 //           "trail_price": null,
                 //           "hwm": null,
                 //           "subtag": null,
                 //           "source": "access_key"
                 //         }
                 //     ]
                 //
                 return this->parseOrders(response, market, since, limit);
               })
        .share();
  }

